"""Replay tables from compact committed measurements, without running routers."""
from pathlib import Path
from statistics import median
import json,gzip,sys
assets,out=map(Path,sys.argv[1:]);load=lambda f:json.loads(gzip.decompress((assets/f).read_bytes())if f.endswith('.gz')else(assets/f).read_bytes())
n=load('native-comparison.json');assert not n['regressions'];rows=n['attempts'];assert len(rows)==78
p95=lambda x:sorted(x)[max(0,__import__('math').ceil(.95*len(x))-1)]
text=['# Component-anchor recovery results','', 'All frozen measurements use the same 26 cases × three repeats, native 10.0.6 checker, host and cores 12–19. Both modes enable the actual public `localRecovery` setting. Before source matches the previous consumer pin; only two engine modules change. Tests and stress jobs overlap the sequential sweeps. Times are descriptive; no causal speed improvement is claimed.','', '| Native mode | Passed /78 | Valid /26 | Opens | Known new errors | Median / p95 s | Total s | Vias | Length sum mm |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
for mode,label in [('before','Previous enabled'),('after','Component anchors enabled')]:
 s=n['summary'][mode];valid=sum(all(r[mode]['passed']for r in rows if r['case']==c)for c in {r['case']for r in rows})
 text.append(f"| {label} | {s['passed']} | {valid} | {s['opens']} | {s['new_errors']} | {s['median_s']:.6f} / {s['p95_s']:.6f} | {s['total_s']:.6f} | {s['vias']} | {s['length_mm']:.6f} |")
changed=[r for r in rows if not r['same_ses']];assert len(changed)==3 and {r['case']for r in changed}=={'rufs-smart-psu-j4'}
text+=['',f"Exactly {n['same_sessions']}/78 session files are identical. Only the three power-supply J4 sessions change: each closes its final GNDA connection with no added vias, 16.377116 mm of full-width track, and zero new native errors. Existing 27 native thermal errors remain unresolved; the whole suite is not DRC clean. Structured error multiplicity, warning geometry and fidelity are compared per attempt; there are zero regressions.",'', '## Every frozen case','', 'Three repeats per cell; p95 of three observations is their maximum. Opens, errors, vias and lengths below are totals across the same three attempts.','', '| Case | Passed before→after /3 | Opens | Errors | Vias | Length sum mm | Median s before→after | p95 s before→after |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
for case in sorted({r['case']for r in rows}):
 rr=[r for r in rows if r['case']==case];parts=[case]
 for k in ['passed','opens','new_errors','vias','length_mm']:
  a,b=[sum(r[m][k]for r in rr)for m in ['before','after']];parts.append(f'{a:.3f}→{b:.3f}'if k=='length_mm'else f'{a}→{b}')
 for f in [median,p95]:parts.append('→'.join(f'{f([r[m]["seconds"]for r in rr]):.6f}'for m in ['before','after']))
 text.append('| '+' | '.join(parts)+' |')
text+=['','## Larger inputs','', 'One exploratory pair per supplied DSN, with two normal passes, 600-second route budget, strict DRC, optimiser/fanout disabled and neck width zero. These are engine checks, not native scores or three-repeat timing studies. All three inputs have zero imported pours; every paired session and complete statistics object is identical.','', '| Input | Incomplete before→after | Exact added / total | Vias | Length mm | Seconds before→after |','| --- | ---: | ---: | ---: | ---: | ---: |']
for p in load('large-comparison.json')['pairs']:
 s=p['stats'];text.append(f"| {p['file']} | {s['connections']['incomplete']}→{s['connections']['incomplete']} | 0 / 0 | {s['barrels']['total']} | {s['tracks']['totalLengthMm']:.6f} | {p['before_s']:.6f}→{p['after_s']:.6f} |")
d=load('dense-comparison.json');assert not d['regressions'];text+=['', 'Prepared Dense6 native export is separate from the supplied DSN above: three repeats/source, same two-pass/600-second budgets.','', '| Prepared Dense6 native | Passed /3 | Opens per repeat | New errors per repeat | Vias per repeat | Length mm per repeat | Median / p95 s |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for m in ['before','after']:
 s=d['summary'][m];text.append(f"| {m.title()} | {s['passed']} | {s['opens']} | {s['new_errors']} | {s['vias']} | {s['length_mm']} | {s['median_s']:.6f} / {s['p95_s']:.6f} |")
text+=['', 'All prepared Dense6 session hashes match; zero introduced findings, warning geometry or fidelity differences. This board remains incomplete, with 181 opens in every repeat. Native prepared input also imports zero pours; this is a nonregression control, not a second pour-recovery gain.']
s=load('slow-comparison.json');text+=['','## Slow acceptance','', 'One current evaluation per unchanged slow case, recovery enabled. Comparison is against the historical enabled sweep; original timed budgets and expectations are retained. These runs cannot establish causal timing or all-input nonregression.','', '| Mode | Passed /63 | Failed | Advisory | Stubs | Sum seconds |','| --- | ---: | ---: | ---: | ---: | ---: |']
for m in ['before','after']:
 v=s['summary'][m];text.append(f"| {m.title()} | {v['passed']} | {v['failed']} | {v['advisory']} | {v['stubbed']} | {v['total_s']:.6f} |")
text+=['',f"Observed adverse per-case differences: {len(s['adverse'])}. Every difference, including timed adverse outcomes, remains in slow-comparison.json. These observations do not justify default promotion."]
for r in s['adverse']:text.append(f"- `{r['id']}`: `{json.dumps(r['measured_differences'],sort_keys=True)}`")
text+=['', 'The final larger and custom native Dense6 driver tool sessions returned 143 after all six case records were written. All per-case native steps exit zero without timeouts; outputs/statistics/source hashes are audited. A successful whole-driver exit is not claimed; see supervisor-observations.json.', '', '## Additional retained evidence','', 'The preliminary native three-repeat J4 subset and first candidate full sweep are retained separately. The first candidate validated alternate anchors rather than the original terminal pair; the final scheduler strengthens that acceptance gate. Neither preliminary execution is relabelled as the final source. Earlier larger-input pairs are also retained separately. See source-audit.json and the frozen hashes for source identity.','', 'The real residual is replayed three times/source with all retained copper unchanged: before 1 open each, after 0 each; exact violations zero throughout, deterministic sessions. The final search uses 3,129 charged work units and closes at margin 4. Seven targeted tests are repeated three times/source: before 2 pass /5 fail, after 7 pass /0 fail. They include both endpoint orientations, isolated copper in a pour hole, sheet incompatibility, a barrel component anchor, rejection of wrong-component anchors, and rollback when an alternate anchor loses its original pour connection.','', 'No new CPU profile is claimed. The profile summary for this change is the recorded recovery work: no normal-pass search changes; a previously unsupported target reaches the existing bounded visibility graph. Full widths, clearances, via sizes, lattice and scheduler budgets remain unchanged. Direct pour contacts, pour-to-pour search, general relaxation and default promotion remain unfinished.','']
out.write_text('\n'.join(text))
